+// https://open-meteo.com/en/docs/air-quality-api
+static QUrl getAirQualityUrl(const QString &latitude, const QString &longitude)
+{
+    QUrl url(AIR_QUALITY_ENDPOINT);
+    QUrlQuery urlQuery = AIR_QUALITY_QUERY;
+    urlQuery.addQueryItem(u"latitude"_s, latitude);
+    urlQuery.addQueryItem(u"longitude"_s, longitude);
+    url.setQuery(urlQuery);
+    return url;
+}
