+
+void OpenMeteoIon::fetchAirQuality(std::shared_ptr<QPromise<std::shared_ptr<Forecast>>> promise,
+                                   std::shared_ptr<Forecast> data,
+                                   LastObservation lastObservation,
+                                   const QString &latitude,
+                                   const QString &longitude)
+{
+    auto job = KIO::storedGet(getAirQualityUrl(latitude, longitude), KIO::Reload, KIO::HideProgressInfo);
+    connect(
+        job,
+        &KJob::result,
+        this,
+        [job, promise, data, lastObservation, this]() mutable {
+            // Air quality is optional, so the forecast is resolved even if this fails
+            if (auto res = validateJob(job); res.has_value()) {
+                const QJsonObject current = res.value()[u"current"_s].toObject();
+                if (current[u"us_aqi"_s].isDouble()) {
+                    lastObservation.setAirQualityIndex(current[u"us_aqi"_s].toInt());
+                }
+                // Pollen data is only available in Europe
+                std::optional<std::pair<QString, double>> pollen;
+                for (const auto &key : POLLEN_KEYS) {
+                    if (!current[key].isDouble()) {
+                        continue;
+                    }
+                    const double count = current[key].toDouble();
+                    if (!pollen.has_value() || count > pollen->second) {
+                        pollen = {key, count};
+                    }
+                }
+                if (pollen.has_value()) {
+                    if (pollen->second > 0) {
+                        lastObservation.setPollen(d->pollenKeyToStrMap.value(pollen->first), pollen->second);
+                    } else {
+                        lastObservation.setPollen(QString(), 0);
+                    }
+                }
+                data->setLastObservation(lastObservation);
+            }
             resolvePromise(*promise, data);
         },
         Qt::SingleShotConnection);
