 void LastObservation::setUVIndex(int UVIndex)
 {
-    // Calculation of UVRating based on https://en.wikipedia.org/wiki/Ultraviolet_index#/media/File:UV_Index_NYC.png
-    // UVIndex can be only from 0 to 10 so don`t assign if the value is out of the range
-    if (UVIndex == 0) {
+    // Calculation of UVRating based on https://en.wikipedia.org/wiki/Ultraviolet_index#Index_usage
+    if (UVIndex < 0) {
+        return;
+    } else if (UVIndex < 3) {
         m_UVRating = i18n("Low");
-    } else if (UVIndex > 0 && UVIndex < 3) {
+    } else if (UVIndex < 6) {
         m_UVRating = i18n("Moderate");
-    } else if (UVIndex >= 3 && UVIndex < 6) {
+    } else if (UVIndex < 8) {
         m_UVRating = i18n("High");
-    } else if (UVIndex >= 6 && UVIndex < 8) {
+    } else if (UVIndex < 11) {
         m_UVRating = i18n("Very high");
-    } else if (UVIndex >= 8 && UVIndex < 11) {
-        m_UVRating = i18n("Extreme");
     } else {
-        return;
+        m_UVRating = i18n("Extreme");
     }
     m_UVIndex = UVIndex;
     m_isDataPresent = true;
 }

+void LastObservation::setAirQualityIndex(int airQualityIndex)
+{
+    // US AQI categories, see https://en.wikipedia.org/wiki/Air_quality_index#United_States
+    if (airQualityIndex < 0) {
+        return;
+    } else if (airQualityIndex <= 50) {
+        m_airQualityRating = i18nc("air quality", "Good");
+    } else if (airQualityIndex <= 100) {
+        m_airQualityRating = i18nc("air quality", "Moderate");
+    } else if (airQualityIndex <= 150) {
+        m_airQualityRating = i18nc("air quality", "Unhealthy for sensitive groups");
+    } else if (airQualityIndex <= 200) {
+        m_airQualityRating = i18nc("air quality", "Unhealthy");
+    } else if (airQualityIndex <= 300) {
+        m_airQualityRating = i18nc("air quality", "Very unhealthy");
+    } else {
+        m_airQualityRating = i18nc("air quality", "Hazardous");
+    }
+    m_airQualityIndex = airQualityIndex;
+    m_isDataPresent = true;
+}
+
+void LastObservation::setPollen(const QString &pollenType, qreal pollenCount)
+{
+    m_pollenType = pollenType;
+    m_pollenCount = pollenCount;
+    m_isDataPresent = true;
+}
